import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { VisitorChartProps, StoreId } from '../types';

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
    dataKey: string;
  }>;
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length > 0) {
    return (
      <div className="custom-tooltip">
        <div className="tooltip-label">{label} の来客実績</div>
        {payload.map((item) => (
          <div key={item.dataKey} className="tooltip-item">
            <span>
              <span
                style={{
                  width: '8px',
                  height: '8px',
                  borderRadius: '50%',
                  backgroundColor: item.color,
                  display: 'inline-block',
                }}
              />
              {item.name}
            </span>
            <span>{item.value?.toLocaleString()} 人</span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

const formatYAxisTick = (val: number): string => {
  if (val >= 10000) {
    const manVal = val / 10000;
    return `${manVal % 1 === 0 ? manVal.toFixed(0) : manVal.toFixed(1)}万人`;
  }
  return `${val.toLocaleString()}人`;
};

const VisitorChart = ({
  data = [],
  stores = [],
  onToggleStore,
}: VisitorChartProps) => {
  const handleLegendClick = (entry: { dataKey?: string | number }) => {
    if (entry && entry.dataKey) {
      onToggleStore?.(entry.dataKey as StoreId);
    }
  };

  return (
    <div className="chart-card">
      <div className="chart-header">
        <h2 className="chart-title">
          <span>月別来客数推移グラフ</span>
        </h2>
        <span className="tag-unit">単位: 人</span>
      </div>

      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={data}
            margin={{ top: 10, right: 24, left: 10, bottom: 0 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
            <XAxis
              dataKey="month"
              stroke="#64748b"
              tickLine={false}
              axisLine={{ stroke: '#cbd5e1' }}
              tick={{ fontSize: 12, fill: '#64748b' }}
            />
            <YAxis
              stroke="#64748b"
              tickLine={false}
              axisLine={{ stroke: '#cbd5e1' }}
              tickFormatter={formatYAxisTick}
              tick={{ fontSize: 12, fill: '#64748b' }}
              width={70}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend
              onClick={handleLegendClick}
              wrapperStyle={{ paddingTop: '16px', cursor: 'pointer', userSelect: 'none' }}
              formatter={(value, entry) => {
                const store = stores.find((s) => s.name === value);
                const isVisible = store ? store.visible : true;
                return (
                  <span
                    style={{
                      color: isVisible ? '#1e293b' : '#94a3b8',
                      textDecoration: isVisible ? 'none' : 'line-through',
                      fontWeight: isVisible ? 600 : 400,
                      fontSize: '0.85rem',
                      marginRight: 12,
                    }}
                  >
                    {value}
                  </span>
                );
              }}
            />
            {stores.map((store) => (
              <Line
                key={store.id}
                type="monotone"
                dataKey={store.id}
                name={store.name}
                stroke={store.color}
                strokeWidth={store.visible ? 3 : 0}
                dot={store.visible ? { r: 4, strokeWidth: 2, fill: '#ffffff', stroke: store.color } : false}
                activeDot={store.visible ? { r: 6, stroke: store.color, strokeWidth: 2, fill: '#ffffff' } : false}
                hide={!store.visible}
                isAnimationActive={true}
                animationDuration={600}
              />
            ))}
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default VisitorChart;

import { StoreSummaryProps, StoreConfig } from '../types';

const StoreSummary = ({ data = [], stores = [] }: StoreSummaryProps) => {
  const calculateMetrics = (store: StoreConfig) => {
    if (data.length === 0) {
      return { total: 0, average: 0, peakMonth: '-', peakCount: 0 };
    }

    let total = 0;
    let peakCount = -1;
    let peakMonth = '';

    for (const item of data) {
      const count = Number(item[store.id]) || 0;
      total += count;
      if (count > peakCount) {
        peakCount = count;
        peakMonth = item.month;
      }
    }

    const average = Math.round(total / data.length);

    return {
      total,
      average,
      peakMonth,
      peakCount: peakCount === -1 ? 0 : peakCount,
    };
  };

  return (
    <div className="summary-grid">
      {stores.map((store) => {
        const metrics = calculateMetrics(store);
        const cardStyle = {
          borderTop: `4px solid ${store.color}`,
          opacity: store.visible ? 1 : 0.6,
        };

        return (
          <div key={store.id} className="summary-card" style={cardStyle}>
            <div className="summary-header">
              <span
                className="summary-dot"
                style={{ backgroundColor: store.color }}
              />
              <span className="summary-name">{store.name}</span>
            </div>

            <div className="summary-metrics">
              <div className="metric-item">
                <span className="metric-title">年間累計</span>
                <span className="metric-value">
                  {metrics.total.toLocaleString()} 人
                </span>
              </div>
              <div className="metric-item">
                <span className="metric-title">月平均</span>
                <span className="metric-value">
                  {metrics.average.toLocaleString()} 人
                </span>
              </div>
              <div className="metric-item">
                <span className="metric-title">ピーク（{metrics.peakMonth}）</span>
                <span className="metric-value">
                  {metrics.peakCount.toLocaleString()} 人
                </span>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default StoreSummary;

import { useState } from 'react';
import { MonthlyVisitorItem, StoreConfig, StoreId } from './types';
import { INITIAL_STORES, INITIAL_MONTHLY_DATA } from './mockData';
import VisitorChart from './components/VisitorChart';
import StoreSummary from './components/StoreSummary';

const App = () => {
  const [stores, setStores] = useState<StoreConfig[]>(INITIAL_STORES);
  const [visitorData, setVisitorData] = useState<MonthlyVisitorItem[]>(INITIAL_MONTHLY_DATA);

  const handleToggleStore = (storeId: StoreId) => {
    setStores((prevStores) =>
      prevStores.map((store) =>
        store.id === storeId ? { ...store, visible: !store.visible } : store
      )
    );
  };

  const handleUpdateCount = (
    month: string,
    storeId: StoreId,
    count: number
  ) => {
    const validCount = isNaN(count) || count < 0 ? 0 : Math.round(count);
    setVisitorData((prevData) =>
      prevData.map((item) =>
        item.month === month ? { ...item, [storeId]: validCount } : item
      )
    );
  };

  const handleResetData = () => {
    setVisitorData(INITIAL_MONTHLY_DATA);
    setStores(INITIAL_STORES);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">店舗別月間来客数 比較ダッシュボード</h1>
        <p className="header-desc">
          渋谷店・新宿店・池袋店の月別来客実績を可視化。店舗ごとの表示切り替えや来客データの直接調整が可能です。
        </p>
      </header>

      <section className="controls-bar">
        <div className="store-filter-group">
          {stores.map((store) => {
            const isActive = store.visible;
            const badgeClass = isActive
              ? 'store-badge store-badge-active'
              : 'store-badge';
            const indicatorStyle = {
              backgroundColor: isActive ? store.color : '#94a3b8',
            };
            const activeStyle = isActive
              ? { borderColor: store.color }
              : undefined;

            return (
              <button
                key={store.id}
                type="button"
                className={badgeClass}
                style={activeStyle}
                onClick={() => handleToggleStore(store.id)}
              >
                <span
                  className="store-badge-indicator"
                  style={indicatorStyle}
                />
                <span>{store.name}</span>
                <span style={{ fontSize: '0.78rem', color: '#64748b' }}>
                  {isActive ? '表示中' : '非表示'}
                </span>
              </button>
            );
          })}
        </div>

        <button
          type="button"
          className="btn-reset"
          onClick={handleResetData}
        >
          <span>初期データに戻す</span>
        </button>
      </section>

      <main className="main-grid">
        <VisitorChart
          data={visitorData}
          stores={stores}
          onToggleStore={handleToggleStore}
        />

        <StoreSummary data={visitorData} stores={stores} />

        <div className="table-card">
          <div className="chart-header">
            <h2 className="table-title">月別来客数データ入力・確認テーブル</h2>
            <span className="tag-unit">数値の直接編集が可能</span>
          </div>
          <div className="table-wrapper">
            <table className="visitor-table">
              <thead>
                <tr>
                  <th>対象月</th>
                  {stores.map((store) => (
                    <th key={store.id}>
                      <span
                        className="summary-dot"
                        style={{
                          backgroundColor: store.color,
                          display: 'inline-block',
                          marginRight: '6px',
                        }}
                      />
                      {store.name} (人)
                    </th>
                  ))}
                  <th>3店舗 合計 (人)</th>
                </tr>
              </thead>
              <tbody>
                {visitorData.map((item) => {
                  const monthlyTotal =
                    (item.shibuya || 0) +
                    (item.shinjuku || 0) +
                    (item.ikebukuro || 0);

                  return (
                    <tr key={item.month}>
                      <td style={{ fontWeight: 700 }}>{item.month}</td>
                      {stores.map((store) => (
                        <td key={store.id}>
                          <input
                            type="number"
                            min="0"
                            step="100"
                            className="visitor-input"
                            value={item[store.id]}
                            disabled={!store.visible}
                            onChange={(e) =>
                              handleUpdateCount(
                                item.month,
                                store.id,
                                parseInt(e.target.value, 10) || 0
                              )
                            }
                          />
                        </td>
                      ))}
                      <td style={{ fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>
                        {monthlyTotal.toLocaleString()}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;
